export declare const auroraGlassTheme = "/* \u6781\u5149\u73BB\u7483\u98CE\u683C */\n#wemd {\n  padding: 5px 20px;\n  max-width: 677px;\n  margin: 0 auto;\n  font-family: -apple-system, BlinkMacSystemFont, \"Helvetica Neue\", \"PingFang SC\", \"Hiragino Sans GB\", \"Microsoft YaHei\", sans-serif;\n  color: #333;\n  /* \u80CC\u666F\u900F\u660E\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u6DF1\u8272\u6A21\u5F0F */\n  background-color: transparent;\n  word-break: break-word;\n}\n\n/* \u6BB5\u843D - \u589E\u52A0\u547C\u5438\u611F */\n#wemd p {\n  margin-top: 22px;\n  margin-bottom: 22px;\n  line-height: 1.9;\n  letter-spacing: 0.6px;\n  text-align: justify;\n  color: #444;\n  font-size: 16px;\n}\n\n/* \u4E00\u7EA7\u6807\u9898 - \u6781\u5149\u8272\u6807\u9898 */\n#wemd h1 {\n  margin-top: 60px;\n  margin-bottom: 50px;\n  text-align: center;\n}\n\n#wemd h1 .content {\n  font-size: 26px;\n  font-weight: 800;\n  display: inline-block;\n  color: #4158D0;\n  line-height: 1.4;\n  padding-bottom: 10px;\n  /* \u5E95\u90E8\u52A0\u4E00\u6761\u6781\u7EC6\u7684\u6E10\u53D8\u7EBF */\n  border-bottom: 2px solid #eee;\n  border-image: linear-gradient(135deg, #4158D0 0%, #C850C0 100%) 1;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n  display: none;\n}\n\n/* \u4E8C\u7EA7\u6807\u9898 - \u60AC\u6D6E\u8272\u5757 */\n#wemd h2 {\n  margin-top: 60px;\n  margin-bottom: 30px;\n  text-align: left;\n}\n\n#wemd h2 .content {\n  display: inline-block;\n  font-size: 18px;\n  font-weight: 700;\n  color: #fff;\n  /* \u767D\u5B57 */\n  background-color: #4158D0;\n  padding: 8px 18px;\n  border-radius: 20px 20px 20px 4px;\n  /* \u4E0D\u5BF9\u79F0\u5706\u89D2\uFF0C\u66F4\u7075\u52A8 */\n  box-shadow: 0 8px 16px rgba(200, 80, 192, 0.3);\n  /* \u5F69\u8272\u5F25\u6563\u6295\u5F71 */\n  line-height: 1.2;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n  display: none;\n}\n\n/* \u4E09\u7EA7\u6807\u9898 - \u534A\u9AD8\u4E0B\u5212\u7EBF */\n#wemd h3 {\n  margin-top: 35px;\n  margin-bottom: 15px;\n}\n\n#wemd h3 .content {\n  font-size: 17px;\n  font-weight: 700;\n  color: #333;\n  display: inline-block;\n  position: relative;\n  box-shadow: inset 0 -0.4em rgba(65, 88, 208, 0.2);\n  padding: 0 4px;\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n  display: none;\n}\n\n/* \n * \u56DB\u7EA7\u6807\u9898 - \u6781\u7B80\u5706\u70B9\n */\n#wemd h4 {\n  margin-top: 24px;\n  margin-bottom: 12px;\n  text-align: left;\n}\n\n#wemd h4 .content {\n  display: inline-block;\n  font-size: 16px;\n  font-weight: 700;\n  color: #4158D0;\n  background-color: #f0f2ff;\n  padding: 4px 12px;\n  border-radius: 12px;\n  line-height: 1.4;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n  display: none;\n}\n\n/* \n * \u5217\u8868 - \u70AB\u5F69\u5706\u70B9\n */\n#wemd ul {\n  list-style-type: disc;\n  padding-left: 20px;\n  margin: 20px 0;\n  color: #C850C0;\n  /* \u5217\u8868\u7B26\u53F7\u7C89\u7D2B\u8272 */\n}\n\n#wemd ul li {\n  margin-bottom: 10px;\n  line-height: 1.8;\n}\n\n#wemd li section {\n  color: #444;\n  /* \u6B63\u6587\u6DF1\u7070 */\n  font-size: 16px;\n}\n\n/* \u6709\u5E8F\u5217\u8868 - \u6E10\u53D8\u8272\u6570\u5B57 (\u901A\u8FC7\u989C\u8272\u6A21\u62DF) */\n#wemd ol {\n  list-style-type: decimal;\n  padding-left: 20px;\n  margin: 20px 0;\n  color: #4158D0;\n  /* \u6570\u5B57\u6DF1\u84DD */\n  font-weight: bold;\n}\n\n#wemd ul ul {\n  list-style-type: circle;\n  color: #4158D0;\n  margin-top: 8px;\n}\n\n#wemd ol ol {\n  list-style-type: lower-roman;\n  color: #C850C0;\n}\n\n#wemd ol li {\n  margin-bottom: 10px;\n  line-height: 1.8;\n}\n\n#wemd ol li section {\n  color: #444;\n  font-weight: normal;\n  font-size: 16px;\n}\n\n/* \n * \u5F15\u7528 - \u78E8\u7802\u73BB\u7483\u5361\u7247\n * \u767D\u5E95 + \u67D4\u548C\u5F69\u8272\u6295\u5F71 + \u7EC6\u5FAE\u8FB9\u6846\n */\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n  margin: 36px 0;\n  padding: 24px;\n  background-color: #fff;\n  border: 1px solid rgba(255, 255, 255, 0.8);\n  /* \u5173\u952E\uFF1A\u53CC\u91CD\u6295\u5F71\uFF0C\u4E00\u5C42\u767D\u5149\uFF0C\u4E00\u5C42\u5F69\u5149 */\n  box-shadow: -4px -4px 10px rgba(255, 255, 255, 0.8), 4px 4px 20px rgba(65, 88, 208, 0.1);\n  border-radius: 16px;\n  /* \u9876\u90E8\u6E10\u53D8\u88C5\u9970\u6761 */\n  border-top: 4px solid #C850C0;\n  overflow: visible !important;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n  margin: 0;\n  color: #555;\n  font-size: 15px;\n  line-height: 1.8;\n}\n\n/* \u94FE\u63A5 - \u6E10\u53D8\u865A\u7EBF */\n#wemd a {\n  color: #C850C0;\n  text-decoration: none;\n  border-bottom: 1px dashed #C850C0;\n  font-weight: 600;\n  padding-bottom: 1px;\n}\n\n/* \u52A0\u7C97 */\n#wemd strong {\n  font-weight: 700;\n  color: #4158D0;\n  margin: 0 1px;\n}\n\n/* \u659C\u4F53 */\n#wemd em {\n  color: #C850C0;\n  font-style: italic;\n}\n\n#wemd em strong {\n  color: #C850C0;\n}\n\n/* \u9AD8\u4EAE */\n#wemd mark {\n    background: rgba(65, 88, 208, 0.15);\n    color: #4158D0;\n    padding: 2px 4px;\n    border-radius: 3px;\n}\n\n/* \u5220\u9664\u7EBF - \u6E10\u53D8\u8272 */\n#wemd del {\n    text-decoration: line-through;\n    color: #999;\n    text-decoration-color: #C850C0;\n}\n\n/* \u5206\u9694\u7EBF - \u6E10\u53D8\u5149\u675F */\n#wemd hr {\n  margin: 60px auto;\n  border: 0;\n  height: 2px;\n  background-image: linear-gradient(90deg, rgba(247, 249, 252, 0) 0%, #C850C0 50%, rgba(247, 249, 252, 0) 100%);\n  width: 80%;\n}\n\n/* \u56FE\u7247 - \u60AC\u6D6E\u6295\u5F71 */\n#wemd img {\n  display: block;\n  margin: 40px auto;\n  width: 100%;\n  border-radius: 12px;\n  /* \u67D4\u548C\u7684\u5F69\u8272\u6295\u5F71 */\n  box-shadow: 0 15px 35px rgba(65, 88, 208, 0.12);\n}\n\n/* \u884C\u5185\u4EE3\u7801 - \u6C14\u6CE1\u98CE\u683C */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n  color: #4158D0;\n  background: #f0f2ff;\n  border: 1px solid rgba(65, 88, 208, 0.1);\n  padding: 3px 6px;\n  margin: 0 4px;\n  border-radius: 6px;\n  font-size: 14px;\n  font-family: sans-serif;\n}\n\n/* \u4EE3\u7801\u5757 - \u6781\u7B80\u6DF1\u8272\u5706\u89D2 */\n/* \u4EE3\u7801\u5757 - \u6CE8\u610F\uFF1A\u4E0D\u8981\u8BBE\u7F6E color\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236\u6587\u5B57\u989C\u8272 */\n#wemd pre code.hljs {\n  display: block;\n  padding: 20px;\n  background: #282c34;\n  /* \u7ECF\u5178\u7684 Atom One Dark */\n  color: #abb2bf;\n  /* \u9ED8\u8BA4\u6587\u5B57\u989C\u8272 */\n  font-size: 13px;\n  line-height: 1.6;\n  border-radius: 12px;\n  font-family: sans-serif;\n  overflow-x: auto;\n  white-space: pre;\n  min-width: max-content;\n  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);\n}\n\n/* \u4F18\u5316\u6DF1\u8272\u80CC\u666F\u4E0B\u7684\u8BED\u6CD5\u9AD8\u4EAE\u989C\u8272 */\n#wemd pre code.hljs .hljs-comment,\n#wemd pre code.hljs .hljs-quote {\n  color: #5c6370;\n}\n\n#wemd pre code.hljs .hljs-keyword,\n#wemd pre code.hljs .hljs-selector-tag {\n  color: #c678dd;\n  font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-string,\n#wemd pre code.hljs .hljs-doctag {\n  color: #98c379;\n}\n\n#wemd pre code.hljs .hljs-number,\n#wemd pre code.hljs .hljs-literal {\n  color: #d19a66;\n}\n\n#wemd pre code.hljs .hljs-title,\n#wemd pre code.hljs .hljs-section {\n  color: #61afef;\n  font-weight: bold;\n}\n\n#wemd pre code.hljs .hljs-built_in,\n#wemd pre code.hljs .hljs-builtin-name {\n  color: #e06c75;\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u7070\u8272 */\n#wemd pre code:not(.hljs) {\n  color: #abb2bf;\n  background: #282c34;\n}\n\n/* \u8868\u683C - \u6E05\u65B0\u98CE\u683C */\n#wemd table {\n  width: 100%;\n  border-collapse: collapse;\n  margin: 40px 0;\n  font-size: 14px;\n  border-radius: 12px;\n  overflow: hidden;\n  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.03);\n  border: 1px solid #f0f0f0;\n}\n\n#wemd table tr th {\n  background: #f4f6f9;\n  color: #4158D0;\n  font-weight: 700;\n  border: 1px solid #f0f0f0;\n  padding: 12px 10px;\n  text-align: left;\n}\n\n#wemd table tr td {\n  border: 1px solid #f0f0f0;\n  padding: 12px 10px;\n  color: #555;\n  background: #fff;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n  color: #4158D0;\n}\n\n#wemd .footnotes-sep {\n  border-top: 1px solid #eee;\n  padding-top: 20px;\n  margin-top: 60px;\n  font-size: 12px;\n  color: #ccc;\n  text-align: center;\n}\n\n#wemd .footnote-num {\n  font-weight: bold;\n  color: #fff;\n  background: #C850C0;\n  border-radius: 50%;\n  width: 16px;\n  height: 16px;\n  display: inline-block;\n  text-align: center;\n  line-height: 16px;\n  font-size: 11px;\n  margin-right: 4px;\n}\n\n#wemd .footnote-item p {\n  color: #999;\n  font-size: 12px;\n  margin: 4px 0;\n}\n\n/* \u516C\u5F0F */\n#wemd .block-equation > svg {\n  max-width: 100% !important;\n}\n\n#wemd .inline-equation > svg {\n  max-width: 100%;\n  vertical-align: middle;\n}\n\n/* \u63D0\u793A\u5757 - \u6781\u5149\u73BB\u7483\u98CE\u683C */\n#wemd .callout {\n  margin: 30px 0;\n  padding: 20px;\n  background: rgba(255, 255, 255, 0.8);\n  backdrop-filter: blur(10px);\n  -webkit-backdrop-filter: blur(10px);\n  border-radius: 12px;\n  border: 1px solid rgba(255, 255, 255, 0.3);\n  box-shadow: 0 8px 20px rgba(65, 88, 208, 0.1);\n}\n\n#wemd .callout-title {\n  font-weight: 700;\n  margin-bottom: 10px;\n  color: #4158D0;\n  font-size: 16px;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n  margin-right: 6px;\n}\n\n#wemd .callout-note {\n  border-left: 4px solid #6366f1;\n}\n\n#wemd .callout-tip {\n  border-left: 4px solid #C850C0;\n}\n\n#wemd .callout-important {\n  border-left: 4px solid #4158D0;\n}\n\n#wemd .callout-warning {\n  border-left: 4px solid #FFCC70;\n}\n\n#wemd .callout-caution {\n  border-left: 4px solid #ef4444;\n}\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
